/* SC Atlas Tracker — dashboard behavior.
 * Loads data/technologies.json (generated by scripts/build_data.py from the
 * source spreadsheet) and renders stat tiles, filters, the technology table,
 * a "recently reviewed" list, and a donut chart of technology types.
 * No build step: open index.html via any static file server.
 */
(function () {
  "use strict";

  var DATA_URL = "data/technologies.json";

  // Fixed categorical slots (dataviz skill palette.md) — assigned once from
  // the full dataset's type_order and never reassigned based on the current
  // filtered view, so a type keeps its color even when other types drop out.
  var SERIES_VARS = ["--series-1", "--series-2", "--series-3", "--series-4", "--series-5"];

  // Ordinal ramp (light -> dark = early -> mature) for stage badges.
  var STAGE_VARS = ["--stage-1", "--stage-2", "--stage-3", "--stage-4", "--stage-5"];

  var state = {
    all: [],
    typeColor: {},
    stageColor: {},
    filters: { company: "", type: "", stage: "", concentration: "" },
    expanded: new Set(),
  };

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  // Only break long compound labels ("Suspension/particle") after the slash,
  // never mid-word — overflow-wrap:anywhere is a last-resort fallback for
  // anything else, not the primary wrapping strategy for these labels.
  function breakable(text) {
    return typeof text === "string" ? text.replace(/\//g, "/​") : text;
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text !== undefined) e.textContent = text;
    return e;
  }

  function fetchData() {
    return fetch(DATA_URL).then(function (res) {
      if (!res.ok) throw new Error("Failed to load " + DATA_URL + " (" + res.status + ")");
      return res.json();
    });
  }

  function buildColorMaps(payload) {
    payload.type_order.forEach(function (type, i) {
      state.typeColor[type] = cssVar(SERIES_VARS[i % SERIES_VARS.length]);
    });
    payload.stage_order.forEach(function (stage) {
      if (stage === "Varies by Program") {
        state.stageColor[stage] = cssVar("--stage-other");
      }
    });
    // Ordinal buckets in maturity order (excludes the "Varies" catch-all,
    // which is handled above as a neutral gray).
    var ordinal = payload.stage_order.filter(function (s) {
      return s !== "Varies by Program";
    });
    ordinal.forEach(function (stage, i) {
      state.stageColor[stage] = cssVar(STAGE_VARS[i % STAGE_VARS.length]);
    });
  }

  function populateSelect(selectEl, values) {
    values.forEach(function (v) {
      var opt = document.createElement("option");
      opt.value = v;
      opt.textContent = v;
      selectEl.appendChild(opt);
    });
  }

  function applyFilters() {
    return state.all.filter(function (t) {
      if (state.filters.company && t.company !== state.filters.company) return false;
      if (state.filters.type && t.type !== state.filters.type) return false;
      if (state.filters.stage && t.stage_bucket !== state.filters.stage) return false;
      if (state.filters.concentration && t.concentration_bucket !== state.filters.concentration) return false;
      return true;
    });
  }

  // ---------- stat tiles ----------

  var ICONS = {
    flask:
      '<path d="M8 2h4M9 2v5.2L4.6 15a2 2 0 0 0 1.8 3h7.2a2 2 0 0 0 1.8-3L11 7.2V2" stroke-linecap="round" stroke-linejoin="round"/>',
    building:
      '<path d="M4 18V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v14M12 8h4a1 1 0 0 1 1 1v9M4 18h14M7 6h1M7 9h1M7 12h1M14 11h1M14 14h1" stroke-linecap="round" stroke-linejoin="round"/>',
    layers:
      '<path d="M10 2 3 6l7 4 7-4-7-4Z" stroke-linejoin="round"/><path d="M3 10l7 4 7-4M3 14l7 4 7-4" stroke-linejoin="round"/>',
    check:
      '<path d="M4 10.5l4 4 8-9" stroke-linecap="round" stroke-linejoin="round"/>',
  };

  function renderStats(payload) {
    var all = payload.technologies;
    var companies = new Set(all.map(function (t) { return t.company; }));
    var types = new Set(all.map(function (t) { return t.type; }).filter(Boolean));
    var approved = all.filter(function (t) { return t.stage_bucket === "Approved / Marketed"; });

    var tiles = [
      { label: "Technologies tracked", value: all.length, sub: "In this snapshot", icon: "flask" },
      { label: "Companies tracked", value: companies.size, sub: "Distinct owners", icon: "building" },
      { label: "Technology types", value: types.size, sub: "Distinct approaches", icon: "layers" },
      { label: "Approved / marketed", value: approved.length, sub: "Already commercial", icon: "check" },
    ];

    var row = document.getElementById("stat-row");
    row.innerHTML = "";
    tiles.forEach(function (t, i) {
      var tile = el("div", "stat-tile");
      var icon = el("div", "stat-icon");
      icon.style.background = cssVar(SERIES_VARS[i % SERIES_VARS.length]);
      icon.innerHTML = '<svg viewBox="0 0 20 20">' + ICONS[t.icon] + "</svg>";
      var body = el("div", "stat-body");
      body.appendChild(el("span", "stat-label", t.label));
      body.appendChild(el("span", "stat-value", String(t.value)));
      body.appendChild(el("span", "stat-sub", t.sub));
      tile.appendChild(icon);
      tile.appendChild(body);
      row.appendChild(tile);
    });
  }

  // ---------- table ----------

  function formatConcentration(t) {
    if (typeof t.concentration_numeric === "number") {
      return t.concentration_numeric.toLocaleString() + " mg/mL";
    }
    return null;
  }

  function renderTable() {
    var rows = applyFilters();
    var tbody = document.getElementById("tech-table-body");
    var template = document.getElementById("row-detail-template");
    tbody.innerHTML = "";

    document.getElementById("table-count").textContent =
      "Showing " + rows.length + " of " + state.all.length + " technologies";

    if (rows.length === 0) {
      var emptyRow = el("tr", "empty-row");
      var emptyCell = document.createElement("td");
      emptyCell.colSpan = 7;
      emptyCell.textContent = "No technologies match the current filters.";
      emptyRow.appendChild(emptyCell);
      tbody.appendChild(emptyRow);
      return;
    }

    rows.forEach(function (t) {
      var tr = el("tr", "tech-row");
      tr.dataset.id = t.id;
      if (state.expanded.has(t.id)) tr.classList.add("is-expanded");

      var nameTd = document.createElement("td");
      nameTd.appendChild(el("span", "tech-name", t.name || t.id));
      nameTd.appendChild(el("span", "tech-id", t.id));
      tr.appendChild(nameTd);

      var companyTd = document.createElement("td");
      companyTd.textContent = t.company || "—";
      tr.appendChild(companyTd);

      var typeTd = document.createElement("td");
      var typeCell = el("div", "type-cell");
      var dot = el("span", "type-dot");
      dot.style.background = state.typeColor[t.type] || cssVar("--text-muted");
      typeCell.appendChild(dot);
      typeCell.appendChild(document.createTextNode(breakable(t.type) || "—"));
      typeTd.appendChild(typeCell);
      tr.appendChild(typeTd);

      var concTd = document.createElement("td");
      var concValue = formatConcentration(t);
      if (concValue) {
        concTd.appendChild(el("span", "concentration-value", concValue));
      } else {
        concTd.appendChild(el("span", "concentration-muted", "Not disclosed"));
      }
      tr.appendChild(concTd);

      var stageTd = document.createElement("td");
      var badge = el("span", "stage-badge", t.stage_bucket || "—");
      var stageBg = state.stageColor[t.stage_bucket] || cssVar("--stage-other");
      badge.style.background = stageBg;
      badge.style.color = isDarkStage(t.stage_bucket) ? "#ffffff" : "#0b0b0b";
      stageTd.appendChild(badge);
      tr.appendChild(stageTd);

      var reviewedTd = document.createElement("td");
      reviewedTd.textContent = t.last_reviewed || "—";
      tr.appendChild(reviewedTd);

      var toggleTd = document.createElement("td");
      var toggleBtn = el("button", "row-toggle");
      toggleBtn.type = "button";
      toggleBtn.setAttribute("aria-label", "Toggle details for " + (t.name || t.id));
      toggleBtn.innerHTML = '<svg viewBox="0 0 20 20"><path d="M7 4l6 6-6 6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
      toggleTd.appendChild(toggleBtn);
      tr.appendChild(toggleTd);

      tbody.appendChild(tr);

      if (state.expanded.has(t.id)) {
        tbody.appendChild(buildDetailRow(template, t));
      }

      tr.addEventListener("click", function (evt) {
        if (evt.target.closest(".row-toggle") === null && evt.target !== tr) {
          // allow clicking anywhere on the row, not just the chevron
        }
        toggleRow(t.id);
      });
    });
  }

  function isDarkStage(bucket) {
    // Slots 3-5 of the ordinal ramp are dark enough to need white text.
    return bucket === "Platform / Feasibility" || bucket === "Pre-registration / Late-stage" || bucket === "Approved / Marketed";
  }

  function buildDetailRow(template, t) {
    var node = template.content.cloneNode(true);
    var tr = node.querySelector(".tech-row-detail");
    node.querySelector(".detail-concentration").textContent = t.concentration_text || "Not disclosed.";
    node.querySelector(".detail-needle").textContent = t.needle_size || "Not disclosed.";
    node.querySelector(".detail-mechanism-text").textContent = t.mechanism || "No mechanism summary on file.";
    return tr;
  }

  function toggleRow(id) {
    if (state.expanded.has(id)) {
      state.expanded.delete(id);
    } else {
      state.expanded.add(id);
    }
    renderTable();
  }

  // ---------- recently reviewed ----------

  function renderRecent() {
    var list = document.getElementById("recent-list");
    list.innerHTML = "";
    var recent = state.all
      .filter(function (t) { return t.last_reviewed; })
      .slice(0, 5);

    recent.forEach(function (t) {
      var li = el("li", "update-item");
      var dot = el("span", "update-dot");
      dot.style.background = state.typeColor[t.type] || cssVar("--text-muted");
      var body = document.createElement("div");
      body.appendChild(el("p", "update-title", t.name || t.id));
      body.appendChild(el("p", "update-meta", t.company + " · " + t.last_reviewed));
      li.appendChild(dot);
      li.appendChild(body);
      list.appendChild(li);
    });

    if (recent.length === 0) {
      list.appendChild(el("li", "update-meta", "No review dates on file."));
    }
  }

  // ---------- donut chart ----------
  // Part-to-whole, at-a-glance, <=6 segments (dataviz skill: choosing-a-form /
  // anti-patterns). Identity is never color-alone: every segment is backed by
  // a legend row with the type name, count, and percentage.

  function renderDonut(payload) {
    var counts = {};
    payload.technologies.forEach(function (t) {
      if (!t.type) return;
      counts[t.type] = (counts[t.type] || 0) + 1;
    });
    var total = payload.technologies.length;
    var order = payload.type_order.filter(function (t) { return counts[t]; });

    var svg = document.getElementById("donut-chart");
    svg.innerHTML = "";
    document.getElementById("donut-total").textContent = String(order.length);

    var cx = 100, cy = 100, r = 80, thickness = 26;
    var gapDeg = 2.5; // surface gap between segments (mark spec: 2px gap equivalent)
    var startAngle = -90;

    order.forEach(function (type) {
      var value = counts[type];
      var fraction = value / total;
      var sweep = fraction * 360 - gapDeg;
      if (sweep < 0) sweep = 0;
      var path = describeArc(cx, cy, r, thickness, startAngle, startAngle + sweep);
      var p = document.createElementNS("http://www.w3.org/2000/svg", "path");
      p.setAttribute("d", path);
      p.setAttribute("fill", state.typeColor[type]);
      var title = document.createElementNS("http://www.w3.org/2000/svg", "title");
      title.textContent = type + ": " + value + " (" + Math.round(fraction * 100) + "%)";
      p.appendChild(title);
      svg.appendChild(p);
      startAngle += fraction * 360;
    });

    var legend = document.getElementById("donut-legend");
    legend.innerHTML = "";
    order.forEach(function (type) {
      var value = counts[type];
      var pct = Math.round((value / total) * 100);
      var li = el("li", "legend-item");
      var swatch = el("span", "legend-swatch");
      swatch.style.background = state.typeColor[type];
      li.appendChild(swatch);
      li.appendChild(el("span", "legend-label", type));
      li.appendChild(el("span", "legend-value", value + " (" + pct + "%)"));
      legend.appendChild(li);
    });
  }

  function polarToCartesian(cx, cy, r, angleDeg) {
    var angleRad = ((angleDeg - 90) * Math.PI) / 180;
    return { x: cx + r * Math.cos(angleRad), y: cy + r * Math.sin(angleRad) };
  }

  function describeArc(cx, cy, r, thickness, startAngle, endAngle) {
    var outerR = r;
    var innerR = r - thickness;
    var startOuter = polarToCartesian(cx, cy, outerR, endAngle);
    var endOuter = polarToCartesian(cx, cy, outerR, startAngle);
    var startInner = polarToCartesian(cx, cy, innerR, endAngle);
    var endInner = polarToCartesian(cx, cy, innerR, startAngle);
    var largeArc = endAngle - startAngle <= 180 ? "0" : "1";
    return [
      "M", startOuter.x, startOuter.y,
      "A", outerR, outerR, 0, largeArc, 0, endOuter.x, endOuter.y,
      "L", endInner.x, endInner.y,
      "A", innerR, innerR, 0, largeArc, 1, startInner.x, startInner.y,
      "Z",
    ].join(" ");
  }

  // ---------- CSV export ----------

  function exportCsv() {
    var rows = applyFilters();
    var header = ["Technology", "Company", "Type", "Concentration (mg/mL)", "Stage", "Last reviewed"];
    var lines = [header.join(",")];
    rows.forEach(function (t) {
      var line = [
        csvEscape(t.name || t.id),
        csvEscape(t.company),
        csvEscape(t.type),
        typeof t.concentration_numeric === "number" ? t.concentration_numeric : "",
        csvEscape(t.stage_bucket),
        csvEscape(t.last_reviewed),
      ];
      lines.push(line.join(","));
    });
    var blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = "sc-atlas-tracker-export.csv";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }

  function csvEscape(value) {
    if (value === null || value === undefined) return "";
    var str = String(value);
    if (/[",\n]/.test(str)) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  }

  // ---------- wiring ----------

  function wireFilters(payload) {
    var companySel = document.getElementById("filter-company");
    var typeSel = document.getElementById("filter-type");
    var stageSel = document.getElementById("filter-stage");
    var concSel = document.getElementById("filter-concentration");

    populateSelect(companySel, payload.company_order);
    populateSelect(typeSel, payload.type_order);
    populateSelect(stageSel, payload.stage_order);
    populateSelect(concSel, payload.concentration_order);

    function onChange() {
      state.filters.company = companySel.value;
      state.filters.type = typeSel.value;
      state.filters.stage = stageSel.value;
      state.filters.concentration = concSel.value;
      renderTable();
    }

    [companySel, typeSel, stageSel, concSel].forEach(function (s) {
      s.addEventListener("change", onChange);
    });

    document.getElementById("reset-filters").addEventListener("click", function () {
      companySel.value = "";
      typeSel.value = "";
      stageSel.value = "";
      concSel.value = "";
      onChange();
    });

    document.getElementById("export-csv").addEventListener("click", exportCsv);
  }

  function init() {
    fetchData()
      .then(function (payload) {
        state.all = payload.technologies;
        buildColorMaps(payload);

        document.getElementById("last-updated").textContent =
          "Last updated: " + (payload.last_updated || "—");

        renderStats(payload);
        wireFilters(payload);
        renderTable();
        renderRecent();
        renderDonut(payload);
      })
      .catch(function (err) {
        var main = document.querySelector(".main");
        var notice = el("div", "panel-card", "Could not load dashboard data: " + err.message);
        main.prepend(notice);
        console.error(err);
      });
  }

  document.addEventListener("DOMContentLoaded", init);
})();
